                    (typeof item_code_val === 'object' && item_code_val !== null) ||
                    Array.isArray(item_code_val) ||
                    !item_code_val;

        if (is_bad) {
            // Use parent item_code value
            let clean_val = parent_item_code;

            console.log(`  Row ${i+1}: Cleaning item_code "${current_str}" (type: ${typeof item_code_val}) -> "${clean_val}"`);

            // CRITICAL: Set directly on row object
            row.item_code = clean_val;

            // Also set via frappe.model.set_value
            try {
                frappe.model.set_value(row.doctype, row.name, 'item_code', clean_val);
                cleaned_count++;
            } catch (e) {
                console.error(`  Error cleaning item_code row ${i+1}:`, e);
            }
        } else {
            // Even if it looks OK, verify it matches parent (optional - only if parent exists)
            if (parent_item_code && current_str !== parent_item_code) {
                // Optionally normalize to parent value for consistency
                // Uncomment if you want all rows to have the same item_code as parent
                // row.item_code = parent_item_code;
                // frappe.model.set_value(row.doctype, row.name, 'item_code', parent_item_code);
            }
        }
    }

    if (cleaned_count > 0) {
        frm.refresh_field(pcb_table_field);
        console.log(`✓ Cleaned ${cleaned_count} item_code values`);
    } else {
        console.log(`✓ All item_code values are already clean`);
    }
    return cleaned_count;
}

