                }
                if (dom_pts2 !== null) {
                    src_from_grid.pts2_status = dom_pts2;
                    console.log('✓ Overrode pts2_status from DOM:', dom_pts2);
                }
                if (dom_pts3 !== null) {
                    src_from_grid.pts3_status = dom_pts3;
                    console.log('✓ Overrode pts3_status from DOM:', dom_pts3);
                }
                if (dom_overall !== null) {
                    src_from_grid.overall_status = dom_overall;
                    console.log('✓ Overrode overall_status from DOM:', dom_overall);
                }
                console.log('✓ Read data directly from grid UI + DOM');
            }
        }
    }

    // Fallback: Read from locals/doc
    let doc_row = frm.doc.pcb_iqc_data_enter[0];
    let src_from_locals = null;
    if (doc_row && doc_row.doctype && doc_row.name && locals[doc_row.doctype] && locals[doc_row.doctype][doc_row.name]) {
        src_from_locals = locals[doc_row.doctype][doc_row.name];
    } else if (doc_row) {
        src_from_locals = doc_row;
    }

    // Use grid data if available (most reliable), otherwise use locals/doc
    let src = src_from_grid || src_from_locals;

    // If we have both, merge (grid wins)
    if (src_from_grid && src_from_locals) {
        try {
            src = Object.assign({}, src_from_locals, src_from_grid);
        } catch (e) {
            src = src_from_grid;
        }
    }

    if (!src || !src.pcb_serial_no) {
        console.log('⚠️ No valid source data or missing serial number');
        return;
    }

    let serial = String(src.pcb_serial_no).trim();
    if (!serial) {
        console.log('⚠️ Serial number is empty');
        return;
    }

    console.log('📋 Captured PCB IQC Data Enter data is', {
        pts1_status: src.pts1_status || 'null',
        pts2_status: src.pts2_status || 'null',
        pts3_status: src.pts3_status || 'null',
        overall_status: src.overall_status || 'null',
        serial: serial
    });

    // Find destination row
    let dest = null;
    let dest_idx = -1;
    for (let i = 0; i < frm.doc[pcb_table_field].length; i++) {
        let r = frm.doc[pcb_table_field][i];
        let r_serial = (r && r.pcb_serial_no) ? String(r.pcb_serial_no).trim() : '';
        if (r && r_serial && r_serial === serial) {
            dest = r;
            dest_idx = i;
            break;
        }
    }

    if (!dest) {
        console.error('❌ ERROR: Could not find destination row in pcb table for serial:', serial);
        console.error('   Available serials:', frm.doc[pcb_table_field].map(r => r.pcb_serial_no));
        return;
    }

    console.log('✓ Found destination row:', {
        name: dest.name,
        serial: dest.pcb_serial_no,
        doctype: dest.doctype,
        idx: dest_idx
    });

    // Normalize select values (trim + exact casing) so updates always stick.
    function normalize_status(val) {
        if (val === undefined || val === null) return null;
        let s = String(val).trim();
        if (!s) return null;
        let upper = s.toUpperCase();
        if (upper === 'PENDING') return 'Pending';
        if (upper === 'PASS') return 'Pass';
        if (upper === 'FAIL') return 'Fail';
        return s; // fallback
    }

    // Clean dominant_channel
    let cleaned_dominant_channel = clean_dominant_channel(src.dominant_channel);
    let pts1_status = normalize_status(src.pts1_status);
    let pts2_status = normalize_status(src.pts2_status);
    let pts3_status = normalize_status(src.pts3_status);

    // Compute overall status automatically from PTS1/PTS2/PTS3 so it never
    // gets stuck at an incorrect value (for example, Pending while all tests
    // are Pass). Rules:
    //   - If ANY test is Fail -> overall = 'Fail'
    //   - Else if ALL three are Pass -> overall = 'Pass'
    //   - Otherwise -> overall = 'Pending'
    function compute_overall_from_pts(p1, p2, p3) {
        let u1 = (p1 || 'Pending').toString().trim().toUpperCase();
        let u2 = (p2 || 'Pending').toString().trim().toUpperCase();
        let u3 = (p3 || 'Pending').toString().trim().toUpperCase();
        if (u1 === 'FAIL' || u2 === 'FAIL' || u3 === 'FAIL') return 'Fail';
        if (u1 === 'PASS' && u2 === 'PASS' && u3 === 'PASS') return 'Pass';
        return 'Pending';
    }

    let overall_status = compute_overall_from_pts(pts1_status, pts2_status, pts3_status);

    // Log BEFORE update (current pcb table values)
    console.log('📊 BEFORE UPDATE - Current pcb table data are', {
        pts1_status: dest.pts1_status || 'null',
        pts2_status: dest.pts2_status || 'null',
        pts3_status: dest.pts3_status || 'null',
        overall_status: dest.overall_status || 'null',
        serial: serial
    });

    console.log('🔄 AFTER UPDATING - New values to sync', {
        pts1_status: pts1_status || 'null',
        pts2_status: pts2_status || 'null',
        pts3_status: pts3_status || 'null',
        overall_status: overall_status || 'null',
        serial: serial
    });

    // Helper to ensure a value is a primitive (string, number, date, null) - prevents circular references
    function ensure_primitive(value) {
        if (value === null || value === undefined) return null;
        if (typeof value === 'number' || typeof value === 'boolean') return value;
        if (value instanceof Date) return value;
        if (typeof value === 'string') {
            // If string contains [object Object], it's a stringified object - try to get from parent
            if (value.indexOf('[object Object]') !== -1) {
                // Try to get from parent form's table_jqbb
                if (frm.doc.table_jqbb) {
                    if (typeof frm.doc.table_jqbb === 'string') return frm.doc.table_jqbb;
                    if (typeof frm.doc.table_jqbb === 'object' && frm.doc.table_jqbb.name) return frm.doc.table_jqbb.name;
                    return String(frm.doc.table_jqbb);
                }
                return ''; // Return empty string if can't resolve
            }
            return value;
        }
        // If it's an object, try to extract a string value
        if (typeof value === 'object') {
            // If it's an array, get first element
            if (Array.isArray(value)) {
                if (value.length > 0) {
                    let first = value[0];
                    if (typeof first === 'object' && first.name) return String(first.name);
                    if (typeof first === 'string') return first;
                    return String(first);
                }
                return null;
            }
            // If it has a 'name' property (common in Frappe Link fields), use that
            if (value.name) return String(value.name);
            // If it has a '__str__' method, use that
            if (typeof value.__str__ === 'function') return String(value.__str__());
            // Otherwise, try to get from parent form
            if (frm.doc.table_jqbb) {
                if (typeof frm.doc.table_jqbb === 'string') return frm.doc.table_jqbb;
                if (typeof frm.doc.table_jqbb === 'object' && frm.doc.table_jqbb.name) return frm.doc.table_jqbb.name;
                return String(frm.doc.table_jqbb);
            }
            return ''; // Return empty string if can't resolve
        }
        return String(value);
    }

    // Helper to set field on child row in a way that Frappe always tracks (important for Pending)
    function set_child_value(row, fieldname, value) {
        // CRITICAL: Ensure value is a primitive to prevent circular references
        let clean_value = ensure_primitive(value);

        // CRITICAL: Check if value actually changed
        let current_value = row[fieldname];
        if (current_value === clean_value) {
            return; // No change needed
        }

        // CRITICAL: Ensure we have the correct doctype
        let row_doctype = row.doctype || 'PCB IQC Line';

        try {
            // Set directly on row object first
            row[fieldname] = clean_value;

            // CRITICAL: Use frappe.model.set_value to ensure Frappe tracks the change
            // Use explicit doctype name to ensure it's correct
            frappe.model.set_value(row_doctype, row.name, fieldname, clean_value);

            // CRITICAL: Mark form as dirty so changes are saved
            frm.dirty();

            console.log(`  ✓ Set ${fieldname}: "${current_value}" -> "${clean_value}" (doctype: ${row_doctype}, name: ${row.name})`);
        } catch (e) {
            console.error(`  ✗ Error setting ${fieldname}:`, e);
            console.error(`    Row doctype: ${row_doctype}, Row name: ${row.name}`);
            // Still try to set directly on row object as fallback
            try {
                row[fieldname] = clean_value;
                frm.dirty();
                console.log(`  ✓ Fallback: Set ${fieldname} directly on row object`);
            } catch (e2) {
                console.error(`  ✗ Fallback also failed for ${fieldname}:`, e2);
            }
        }
    }

    // Update dest row object directly (what gets saved with parent doc)
    // CRITICAL: Ensure item_code is always a string, not an object reference
    let item_code_value = src.item_code;
    // Use ensure_primitive to handle all cases (objects, arrays, stringified objects)
    item_code_value = ensure_primitive(item_code_value);
    // If still not valid, get from parent
    if (!item_code_value || item_code_value === '[object Object]' || String(item_code_value).indexOf('[object Object]') !== -1) {
        item_code_value = get_parent_item_code(frm);
    }
    // Final validation - must be a clean string
    if (!item_code_value || typeof item_code_value !== 'string' || item_code_value.indexOf('[object Object]') !== -1) {
        item_code_value = get_parent_item_code(frm) || '';
    }
    set_child_value(dest, 'item_code', item_code_value);

    // IMPORTANT: set EXACT value (no fallbacks) so "anything -> anything" works
    if (overall_status !== null) set_child_value(dest, 'overall_status', overall_status);
    set_child_value(dest, 'iqc_date', src.iqc_date || dest.iqc_date || frappe.datetime.get_today());

    if (pts1_status !== null) set_child_value(dest, 'pts1_status', pts1_status);
    set_child_value(dest, 'pts1_date', (pts1_status === 'Pending') ? null : (src.pts1_date || dest.pts1_date));

    if (pts2_status !== null) set_child_value(dest, 'pts2_status', pts2_status);
    set_child_value(dest, 'pts2_date', (pts2_status === 'Pending') ? null : (src.pts2_date || dest.pts2_date));

    if (pts3_status !== null) set_child_value(dest, 'pts3_status', pts3_status);
    set_child_value(dest, 'pts3_date', (pts3_status === 'Pending') ? null : (src.pts3_date || dest.pts3_date));

    set_child_value(dest, 'dominant_channel', cleaned_dominant_channel);
    set_child_value(dest, 'max_value', src.max_value);
    set_child_value(dest, 'remarks', src.remarks);

    // Ensure parent fields are correct (safety)
    dest.parent = frm.doc.name;
    dest.parenttype = 'PCB IQC Result';
    dest.parentfield = pcb_table_field;

    // CRITICAL: Verify values were actually set BEFORE refresh
    console.log('🔍 VERIFICATION - Values in dest row object:', {
        pts1_status: dest.pts1_status || 'null',
        pts2_status: dest.pts2_status || 'null',
        pts3_status: dest.pts3_status || 'null',
        overall_status: dest.overall_status || 'null',
        serial: serial
    });

    // CRITICAL: Mark form as dirty AFTER all updates to ensure changes are saved
    frm.dirty();

    // CRITICAL: Refresh the field to update UI
    frm.refresh_field(pcb_table_field);

    console.log('✓ Form marked as dirty and field refreshed');

    // Log AFTER update (verify pcb table values were updated)
    setTimeout(function() {
        // Re-read from pcb table to verify
        let updated_dest = null;
        for (let i = 0; i < frm.doc[pcb_table_field].length; i++) {
            let r = frm.doc[pcb_table_field][i];
            let r_serial = (r && r.pcb_serial_no) ? String(r.pcb_serial_no).trim() : '';
            if (r && r_serial && r_serial === serial) {
                updated_dest = r;
                break;
            }
        }

        if (updated_dest) {
            console.log('✅ UPDATED pcb table data are', {
                pts1_status: updated_dest.pts1_status || 'null',
                pts2_status: updated_dest.pts2_status || 'null',
                pts3_status: updated_dest.pts3_status || 'null',
                overall_status: updated_dest.overall_status || 'null',
                serial: serial
            });

            // CRITICAL: Verify values match what we tried to set
            let values_match = (
                (updated_dest.pts1_status === pts1_status || (!updated_dest.pts1_status && !pts1_status)) &&
                (updated_dest.pts2_status === pts2_status || (!updated_dest.pts2_status && !pts2_status)) &&
                (updated_dest.pts3_status === pts3_status || (!updated_dest.pts3_status && !pts3_status)) &&
                (updated_dest.overall_status === overall_status || (!updated_dest.overall_status && !overall_status))
            );

            if (!values_match) {
                console.error('❌ WARNING: Values do not match! Expected:', {
                    pts1_status: pts1_status,
                    pts2_status: pts2_status,
                    pts3_status: pts3_status,
                    overall_status: overall_status
                }, 'Got:', {
                    pts1_status: updated_dest.pts1_status,
                    pts2_status: updated_dest.pts2_status,
                    pts3_status: updated_dest.pts3_status,
                    overall_status: updated_dest.overall_status
                });
            } else {
                console.log('✅ All values match expected values');
            }
        } else {
            console.error('❌ ERROR: Could not find updated row after sync!');
        }
        console.log('=== SYNC COMPLETED ===');
    }, 200);
}

// Attach handlers to buttons (they're already in the HTML field)
function attach_button_handlers(frm) {
    setTimeout(function() {
        // Remove old handlers first
        $('.pcb-submit-btn').off('click');
        $('.pcb-search-btn').off('click');
        $('.pcb-filter-btn').off('click');
        $('.pcb-update-btn').off('click');

        // Attach new handlers
        $('.pcb-submit-btn').on('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            console.log('Submit button clicked');
            submit_pcb_data(frm);
        });

        $('.pcb-search-btn').on('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            console.log('Search button clicked');
            search_pcb_serial(frm);
        });

        $('.pcb-filter-btn').on('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            console.log('Filter button clicked');
            filter_by_batch(frm);
        });

                // Inline Update button -> trigger the same primary-action (blue Update)
        // button as the top-right toolbar, but only when it is an active
        // Update/Save action. When the header only shows "Cancel", this
        // button will do nothing. If the primary button cannot be detected
        // but the form is dirty, we fall back to frm.save().
        $('.pcb-update-btn').on('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            console.log('Inline Update button clicked');

            function form_is_dirty(frm) {
                try {
                    if (typeof frm.is_dirty === 'function') {
                        return !!frm.is_dirty();
                    }
                    if (typeof frm.dirty === 'boolean') {
                        return !!frm.dirty;
                    }
                    if (frm.doc && typeof frm.doc.__unsaved !== 'undefined') {
                        return !!frm.doc.__unsaved;
                    }
                } catch (err) {
                    console.error('Error checking dirty state:', err);
                }
                return false;
            }

            var $primary = $('.primary-action:visible');
            var primary_used = false;

            if ($primary && $primary.length) {
                var rawLabel = $primary.attr('data-label') || $primary.text() || '';
                var label = String(rawLabel).trim().toLowerCase();
                var isDisabled = $primary.is(':disabled') || $primary.hasClass('disabled');

                console.log('Inline Update: primary label=', label, 'disabled=', isDisabled);

                if (!isDisabled && (label === 'update' || label === 'save')) {
                    primary_used = true;
                    $primary.click();
                    return;
                }
            }

            // If the form is not dirty, do absolutely nothing.
            if (!form_is_dirty(frm)) {
                console.log('Inline Update: form is clean; no Save/Update will be triggered.');
                return;
            }

            // Fallback: if form is dirty but primary action is not detectable,
            // call frm.save() directly so behaviour still matches the header.
            console.log('Inline Update: falling back to frm.save()');
            try {
                if (typeof frm.save === 'function') {
                    frm.save();
                } else if (typeof frm.save_or_update === 'function') {
                    frm.save_or_update();
                }
            } catch (err2) {
                console.error('Inline Update: error calling frm.save():', err2);
            }
        });
    }, 500);
}

// Search PCB in pcb table - FIXED: Handle new documents properly
// Prevent duplicate calls
var search_in_progress = false;

function search_pcb_in_table(frm) {
    console.log('=== SEARCH PCB IN TABLE STARTED ===');
    console.log('Document name:', frm.doc.name);
    console.log('Document is_new:', frm.is_new());
    console.log('pcb_scan value:', frm.doc.pcb_scan);

    // Prevent duplicate calls
    if (search_in_progress) {
        console.log('⚠️ Search already in progress, skipping...');
        return;
    }

    if (!frm.doc.pcb_scan) {
        console.log('ERROR: No serial number in pcb_scan field');
        return;
    }

    let serial_no = frm.doc.pcb_scan.trim();
    if (!serial_no) {
        console.log('ERROR: Serial number is empty after trim');
        return;
    }

    console.log('✓ Searching for PCB:', serial_no);
    search_in_progress = true;

    // CRITICAL: If document is new, auto-save it first (silently)
    if (frm.is_new()) {
        // Check if required fields are filled
        // Only require PCB item (header field); table_jqbb can be empty on a new document
        if (!frm.doc.pcb) {
            search_in_progress = false;
            frappe.msgprint(__('Please select PCB Item first before scanning serial number'));
            return;
        }

        // CRITICAL FIX: Check if this is an amended document (declare outside block for scope)
        let is_amended = frm.doc.amended_from ? true : false;
        let saved_pcb_data = null;
        let pcb_table_field = 'table_jqbb';

        console.log('Document is new. Is amended?', is_amended);
        if (is_amended) {
            console.log('Amended from:', frm.doc.amended_from);
            console.log('⚠️ PRESERVING existing pcb table data (amended document)');
        }

        // CRITICAL: Only clear PCB IQC Data Enter table (always safe to clear)
        // BUT: DO NOT clear pcb table if this is an amended document - preserve existing data!
        console.log('Clearing PCB IQC Data Enter table before save...');
        try {
            if (frm.fields_dict['pcb_iqc_data_enter'] && frm.doc.pcb_iqc_data_enter) {
                frm.clear_table('pcb_iqc_data_enter');
            }
        } catch(e) {
            console.log('Could not clear pcb_iqc_data_enter:', e);
        }

        // ONLY clear pcb table if this is NOT an amended document
        if (!is_amended) {
            console.log('Clearing pcb table (new document, not amended)...');
            try {
                if (frm.fields_dict[pcb_table_field] && frm.doc[pcb_table_field]) {
                    frm.clear_table(pcb_table_field);
                }
            } catch(e) {
                console.log('Could not clear pcb table:', e);
            }
        } else {
            console.log('✓ Preserving pcb table data (amended document)');
            // CRITICAL FIX: For amended documents, we need to temporarily clear pcb table rows
            // because they reference the old parent document name, which causes validation errors
            // We'll restore them after saving with correct parent references
            if (frm.doc[pcb_table_field] && frm.doc[pcb_table_field].length > 0) {
                console.log('Temporarily saving', frm.doc[pcb_table_field].length, 'pcb table rows...');
                // Save a copy of the data (without parent references)
                saved_pcb_data = [];
                for (let i = 0; i < frm.doc[pcb_table_field].length; i++) {
                    let row = frm.doc[pcb_table_field][i];
                    // Create a clean copy without parent fields (they'll be set after save)
                    let row_copy = {};
                    for (let key in row) {
                        if (key !== 'parent' && key !== 'parenttype' && key !== 'parentfield' && key !== 'name' && key !== '__islocal' && key !== '__unsaved') {
                            row_copy[key] = row[key];
                        }
                    }
                    saved_pcb_data.push(row_copy);
                }
                console.log('✓ Saved pcb table data temporarily');
                // Clear the table to avoid validation errors
                console.log('Clearing pcb table temporarily to avoid parent reference errors...');
                frm.clear_table(pcb_table_field);
            }
        }

        // Auto-save the document first
        console.log('Document is new, saving first...');
        frm.save().then(function() {
            console.log('✓ Document saved successfully, reloading form...');
            // CRITICAL: Reload form to get actual document name before adding child rows
            frm.reload_doc();
            setTimeout(function() {
                console.log('✓ Form reloaded, now restoring pcb table data...');

                // If this was an amended document, restore the pcb table data
                if (is_amended && saved_pcb_data && saved_pcb_data.length > 0) {
                    console.log('Restoring', saved_pcb_data.length, 'pcb table rows with correct parent references...');
                    for (let i = 0; i < saved_pcb_data.length; i++) {
                        let row_data = saved_pcb_data[i];
                        let new_row = frm.add_child(pcb_table_field);
                        // Copy all data
                        for (let key in row_data) {
                            new_row[key] = row_data[key];
                        }
                        // Set correct parent references
                        new_row.parent = frm.doc.name;
                        new_row.parenttype = 'PCB IQC Result';
                        new_row.parentfield = pcb_table_field;
                        console.log(` ✓ Restored row ${i}: ${row_data.pcb_serial_no}`);
                    }
                    frm.refresh_field(pcb_table_field);
                    console.log('✓ pcb table data restored');
                }

                // Now add the scanned PCB
                console.log('Now adding scanned PCB...');
                add_pcb_to_tables(frm, serial_no);
                // search_in_progress will be reset in add_pcb_to_tables
            }, 800); // Increased timeout for reload to complete
        }).catch(function(err) {
            console.error('ERROR saving document:', err);
            search_in_progress = false;
            frappe.msgprint(__('Could not save document. Please check required fields and try again.'));
            console.log('=== SEARCH PCB IN TABLE FAILED (SAVE ERROR) ===');
        });
        return;
    }

    // Document is saved - proceed normally
    console.log('Document is already saved, proceeding to add PCB...');
    add_pcb_to_tables(frm, serial_no);
    // search_in_progress will be reset in add_pcb_to_tables
}

// Helper function to clean and validate dominant_channel value
function clean_dominant_channel(value) {
    if (!value) return null;

    // Valid values only
    var valid_values = ['Balanced', 'Left', 'Right'];

    // Convert to string
    var str_value = String(value);

    // Check if it's exactly a valid value (after trimming)
    var trimmed = str_value.trim();
    for (var i = 0; i < valid_values.length; i++) {
        if (trimmed === valid_values[i]) {
            return trimmed;
        }
    }

    // If it contains multiple values, find first valid one
    // Check if any valid value appears in the string
    for (var j = 0; j < valid_values.length; j++) {
        if (str_value.indexOf(valid_values[j]) !== -1) {
            return valid_values[j];
        }
    }

    // If no valid value found, return null
    return null;
}

// Helper function to add PCB to tables
function add_pcb_to_tables(frm, serial_no) {
    console.log('=== ADD PCB TO TABLES STARTED ===');
    console.log('Serial number:', serial_no);
    console.log('Document name:', frm.doc.name);
    console.log('Document is_new:', frm.is_new());

    // Check if this is an amended document
    let is_amended = frm.doc.amended_from ? true : false;
    if (is_amended) {
        console.log('📋 AMENDED DOCUMENT - Preserving existing pcb table data');
        console.log('Amended from:', frm.doc.amended_from);
    }

    let pcb_table_field = 'table_jqbb';
    let found_pcb = null;

    // Search in pcb table (bottom table)
    if (frm.doc[pcb_table_field] && frm.doc[pcb_table_field].length > 0) {
        console.log('Checking', frm.doc[pcb_table_field].length, 'rows in pcb table');
        for (let i = 0; i < frm.doc[pcb_table_field].length; i++) {
            let row = frm.doc[pcb_table_field][i];
            console.log(' Row', i, 'serial:', row.pcb_serial_no);
            if (row.pcb_serial_no === serial_no) {
                found_pcb = row;
                console.log('✓ Found PCB at row', i, ':', found_pcb);
                if (is_amended) {
                    console.log('📋 Loading existing test results from amended document');
                }
                break;
            }
        }
    } else {
        console.log('pcb table is empty');
        if (is_amended) {
            console.log('⚠️ WARNING: Amended document but pcb table is empty - this should not happen!');
        }
    }

    // Clear top table first
    console.log('Clearing PCB IQC Data Enter table...');
    frm.clear_table('pcb_iqc_data_enter');

    // CRITICAL: Ensure document is saved before adding child rows
    if (frm.is_new()) {
        console.error('ERROR: Document is still new - cannot add child rows');
        frappe.msgprint(__('Please save the document first before scanning PCB serial numbers'));
        return;
    }

    // Add row to PCB IQC Data Enter table (first row only)
    console.log('Adding row to PCB IQC Data Enter table...');
    let row = frm.add_child('pcb_iqc_data_enter');
    console.log('✓ Row added, name:', row.name);

    // CRITICAL: Explicitly set parent fields to ensure they're correct
    if (row) {
        row.parent = frm.doc.name;
        row.parenttype = 'PCB IQC Result';
        row.parentfield = 'pcb_iqc_data_enter';
        console.log('✓ Parent fields set:', { parent: row.parent, parenttype: row.parenttype, parentfield: row.parentfield });
    }

    if (found_pcb) {
        console.log('PCB FOUND - Loading existing data into PCB IQC Data Enter table');
        // PCB found in pcb table - populate with existing data
        // CRITICAL: Clean dominant_channel value to prevent validation errors
        let cleaned_dominant_channel = clean_dominant_channel(found_pcb.dominant_channel);
        console.log('Cleaned dominant_channel:', cleaned_dominant_channel, '(original:', found_pcb.dominant_channel, ')');

        console.log('Setting values in PCB IQC Data Enter row...');
        // CRITICAL: Ensure item_code is always a string, not an object
        let item_code_val = found_pcb.item_code;
        if (!item_code_val || typeof item_code_val !== 'string' || String(item_code_val).indexOf('[object Object]') !== -1) {
