                // Re-get from parent (shouldn't happen, but safety check)
                clean_item_code = get_parent_item_code(frm) || '';
            }

            // Set item_code directly on row object
            new_pcb_row.item_code = clean_item_code;
            // Also set via frappe.model.set_value to ensure Frappe tracks it
            try {
