            console.log('✓ Parent fields set in pcb table row:', { 
                parent: new_pcb_row.parent, 
                parenttype: new_pcb_row.parenttype, 
                parentfield: new_pcb_row.parentfield, 
                item_code: new_pcb_row.item_code,
                item_code_type: typeof new_pcb_row.item_code
            });

            // CRITICAL: Verify item_code is clean after setting (Frappe might have changed it)
            setTimeout(function() {
                let current_item_code = new_pcb_row.item_code;
                let current_str = String(current_item_code || '');
                if (current_str.indexOf('[object Object]') !== -1 || typeof current_item_code === 'object') {
                    console.log('⚠️ item_code became object after setting, fixing...');
                    new_pcb_row.item_code = clean_item_code;
                    try {
                        frappe.model.set_value(new_pcb_row.doctype, new_pcb_row.name, 'item_code', clean_item_code);
                    } catch (e) {
                        console.error('Error re-setting item_code:', e);
                    }
