            }, 100);
        }

        frm.refresh_field(pcb_table_field);
        console.log('✓ pcb table field refreshed');

        // CRITICAL: Clean all item_code values after adding new row to catch any issues
        setTimeout(function() {
            clean_all_item_codes(frm);
        }, 200);

        frappe.show_alert({ message: __('New PCB added! Enter PTS testing details'), indicator: 'orange' }, 3);
        console.log('=== ADD PCB TO TABLES COMPLETED (NEW) ===');
    }

    frm.refresh_field('pcb_iqc_data_enter');
    console.log('✓ PCB IQC Data Enter field refreshed');
    setTimeout(() => {
        apply_status_colors(frm);
        // CRITICAL: Attach grid listeners after adding row so changes are captured
        attach_grid_change_listeners(frm);
        frm.set_value('pcb_scan', '');
        frm.set_value('iqc_remarks', '');
        console.log('✓ Scan field cleared');
        search_in_progress = false;
    }, 300);
}

// Submit PCB Data - Update existing row in pcb table
function submit_pcb_data(frm) {
    console.log('=== SUBMIT PCB DATA STARTED ===');
    console.log('Document name:', frm.doc.name);
    console.log('Document is_new:', frm.is_new());
    console.log('PCB IQC Data Enter rows:', frm.doc.pcb_iqc_data_enter ? frm.doc.pcb_iqc_data_enter.length : 0);

    if (!frm.doc.pcb_iqc_data_enter || frm.doc.pcb_iqc_data_enter.length === 0) {
        console.log('ERROR: PCB IQC Data Enter table is empty');
        frappe.msgprint(__('Please enter PCB data in PCB IQC Data Enter table'));
        return;
    }

    // CRITICAL: Get the latest data from the grid widget to ensure we have UI changes
    let pcb_data = null;
    // Try to get data from grid widget first (most up-to-date)
    if (frm.fields_dict['pcb_iqc_data_enter'] && frm.fields_dict['pcb_iqc_data_enter'].grid && frm.fields_dict['pcb_iqc_data_enter'].grid.data.length > 0) {
        pcb_data = frm.fields_dict['pcb_iqc_data_enter'].grid.data[0];
        console.log('✓ Got data from grid widget');
    } else {
        // Fallback to doc object
        pcb_data = frm.doc.pcb_iqc_data_enter[0];
        console.log('✓ Got data from doc object');
    }

    console.log('PCB Data from table:', JSON.stringify(pcb_data, null, 2));

    // Tie header Remarks field (iqc_remarks) to this serial as per-row remark
    try {
        pcb_data.remarks = (frm.doc.iqc_remarks || '').trim();
        console.log('Using header remark for this serial:', pcb_data.remarks);
    } catch (e) {
        console.error('Error binding header remark to pcb_data.remarks:', e);
    }

    // CRITICAL: Clean dominant_channel immediately when reading from table
    if (pcb_data.dominant_channel) {
        pcb_data.dominant_channel = clean_dominant_channel(pcb_data.dominant_channel);
        console.log('Cleaned dominant_channel from PCB IQC Data Enter:', pcb_data.dominant_channel);
    }

    if (!pcb_data.pcb_serial_no) {
        console.log('ERROR: PCB Serial Number is missing');
        frappe.msgprint(__('PCB Serial Number is required'));
        return;
    }

    console.log('Looking for PCB serial:', pcb_data.pcb_serial_no);
    console.log('PTS1 Status from form:', pcb_data.pts1_status);

    // FIX: Ensure document is saved before submitting
    if (frm.is_new()) {
        console.log('ERROR: Document is new, cannot submit');
        frappe.msgprint(__('Please save the document first before submitting PCB data'));
        return;
    }

    let pcb_table_field = 'table_jqbb';
    let exists_in_pcb = false;
    let existing_row_name = null;
    let existing_row_index = -1;

    // Find existing row in pcb table
    console.log('Searching in pcb table, total rows:', frm.doc[pcb_table_field] ? frm.doc[pcb_table_field].length : 0);
    if (frm.doc[pcb_table_field] && frm.doc[pcb_table_field].length > 0) {
        for (let i = 0; i < frm.doc[pcb_table_field].length; i++) {
            console.log(' Row', i, 'serial:', frm.doc[pcb_table_field][i].pcb_serial_no);
            if (frm.doc[pcb_table_field][i].pcb_serial_no === pcb_data.pcb_serial_no) {
                exists_in_pcb = true;
                existing_row_name = frm.doc[pcb_table_field][i].name;
                existing_row_index = i;
                console.log(' ✓ Found matching PCB at row', i, 'name:', existing_row_name);
                break;
            }
        }
    }

    if (!exists_in_pcb) {
        console.log('ERROR: PCB not found in pcb table');
        frappe.msgprint(__('PCB not found in pcb table. Please scan the serial number first.'));
        return;
    }

    // Update existing row in pcb table with data from PCB IQC Data Enter
    try {
        console.log('Preparing to update row:', existing_row_name, 'at index:', existing_row_index);
        console.log('Current PCB data to update:', {
            'pts1_status': pcb_data.pts1_status,
            'pts2_status': pcb_data.pts2_status,
            'pts3_status': pcb_data.pts3_status,
            'overall_status': pcb_data.overall_status,
            'dominant_channel': pcb_data.dominant_channel
        });

        // CRITICAL: Clean dominant_channel value to prevent validation errors
        let cleaned_dominant_channel = clean_dominant_channel(pcb_data.dominant_channel);
        console.log('Cleaned dominant_channel:', cleaned_dominant_channel, '(original:', pcb_data.dominant_channel, ')');

        // Find the actual row object in the form
        let row_to_update = frm.doc[pcb_table_field][existing_row_index];
        if (!row_to_update) {
            console.error('ERROR: Could not find row object for:', existing_row_name);
            frappe.msgprint(__('Error: Could not find PCB row to update'));
            return;
        }

        console.log('Current row values BEFORE update:', {
            'pts1_status': row_to_update.pts1_status,
            'pts2_status': row_to_update.pts2_status,
            'pts3_status': row_to_update.pts3_status,
            'overall_status': row_to_update.overall_status
        });

        // CRITICAL: Update ALL fields using frappe.model.set_value (this ensures ERPNext registers the changes)
        console.log('Updating row via frappe.model.set_value...');
        // CRITICAL: Ensure item_code is always a string, not an object
        let submit_item_code = pcb_data.item_code;
        if (!submit_item_code || typeof submit_item_code !== 'string' || String(submit_item_code).indexOf('[object Object]') !== -1) {
            submit_item_code = get_parent_item_code(frm);
        }
        frappe.model.set_value('PCB IQC Line', existing_row_name, {
            'item_code': submit_item_code,
            'overall_status': pcb_data.overall_status || 'Pending',
            'iqc_date': pcb_data.iqc_date || frappe.datetime.get_today(),
            'pts1_status': pcb_data.pts1_status || 'Pending',
            'pts1_date': pcb_data.pts1_date,
            'pts2_status': pcb_data.pts2_status || 'Pending',
            'pts2_date': pcb_data.pts2_date,
            'pts3_status': pcb_data.pts3_status || 'Pending',
            'pts3_date': pcb_data.pts3_date,
            'dominant_channel': cleaned_dominant_channel,
            'max_value': pcb_data.max_value,
            'remarks': pcb_data.remarks
        });
        console.log('✓ Row updated via frappe.model.set_value');

        // Also update the row object directly to ensure UI reflects changes immediately
        row_to_update.item_code = submit_item_code;
        row_to_update.overall_status = pcb_data.overall_status || 'Pending';
        row_to_update.iqc_date = pcb_data.iqc_date || frappe.datetime.get_today();
        row_to_update.pts1_status = pcb_data.pts1_status || 'Pending';
        row_to_update.pts1_date = pcb_data.pts1_date;
        row_to_update.pts2_status = pcb_data.pts2_status || 'Pending';
        row_to_update.pts2_date = pcb_data.pts2_date;
        row_to_update.pts3_status = pcb_data.pts3_status || 'Pending';
        row_to_update.pts3_date = pcb_data.pts3_date;
        row_to_update.dominant_channel = cleaned_dominant_channel;
        row_to_update.max_value = pcb_data.max_value;
        row_to_update.remarks = pcb_data.remarks;

        console.log('✓ Row updated directly');
        console.log('Updated row values:', {
            'overall_status': row_to_update.overall_status,
            'pts1_status': row_to_update.pts1_status,
            'pts2_status': row_to_update.pts2_status,
            'pts3_status': row_to_update.pts3_status
        });

        frm.refresh_field(pcb_table_field);
        console.log('✓ pcb table field refreshed');

        // CRITICAL FIX: Clear PCB IQC Data Enter table BEFORE saving to avoid validation errors
        console.log('Clearing PCB IQC Data Enter table before save...');
        frm.clear_table('pcb_iqc_data_enter');
        frm.refresh_field('pcb_iqc_data_enter');
        console.log('✓ PCB IQC Data Enter table cleared');

        // CRITICAL FIX: Save FIRST to persist changes, then reload to refresh form
        console.log('Saving document to persist changes...');
        frm.save().then(function() {
            console.log('✓ Document saved successfully');
            frappe.show_alert({ message: __('PCB data updated successfully'), indicator: 'green' }, 5);

            // Reload document AFTER save to refresh form with latest data
            console.log('Reloading document to refresh form...');
            setTimeout(function() {
                frm.reload_doc();
                console.log('=== SUBMIT PCB DATA COMPLETED ===');
                // After reload, focus pcb_scan so the operator can immediately scan next PCB
                setTimeout(function() {
                    try {
                        if (frm.fields_dict['pcb_scan'] && frm.fields_dict['pcb_scan'].$input) {
                            frm.fields_dict['pcb_scan'].$input.focus();
                            frm.fields_dict['pcb_scan'].$input.select();
                        }
                    } catch (e) {
                        console.error('Error focusing pcb_scan after submit:', e);
                    }
                }, 300);
            }, 500);
        }).catch(function(err) {
            console.error('ERROR saving document:', err);
            console.error('Error details:', err);
            let err_msg = err.message || err.exc || String(err);
            console.error('Error message:', err_msg);

            // Check if it's a dominant_channel validation error
            if (err_msg && (err_msg.indexOf('Dominant Channel') !== -1 || err_msg.indexOf('dominant_channel') !== -1)) {
                console.log('Dominant Channel validation error detected');
                console.log('Attempting to fix by cleaning all dominant_channel values...');

                // Clean dominant_channel in pcb table rows
                if (frm.doc[pcb_table_field] && frm.doc[pcb_table_field].length > 0) {
                    for (let i = 0; i < frm.doc[pcb_table_field].length; i++) {
                        let row = frm.doc[pcb_table_field][i];
                        if (row.dominant_channel) {
                            let cleaned = clean_dominant_channel(row.dominant_channel);
                            if (cleaned !== row.dominant_channel) {
                                console.log(`Cleaning row ${i} dominant_channel: "${row.dominant_channel}" -> "${cleaned}"`);
                                frappe.model.set_value('PCB IQC Line', row.name, { 'dominant_channel': cleaned });
                            }
                        }
                    }
                    frm.refresh_field(pcb_table_field);
                }

                // Retry save after cleaning
                setTimeout(function() {
                    frm.save().then(function() {
                        console.log('✓ Document saved after cleaning dominant_channel');
                        frappe.show_alert({ message: __('PCB data updated successfully'), indicator: 'green' }, 5);
                        frm.reload_doc();
                    }).catch(function(retry_err) {
                        console.error('ERROR on retry save after cleaning:', retry_err);
                        frappe.msgprint(__('Error saving document: {0}', [retry_err.message || 'Unknown error']));
                    });
                }, 300);
            }
            // Check if it's a timestamp mismatch error
            else if (err_msg && err_msg.indexOf('modified') !== -1) {
                console.log('Timestamp mismatch detected, reloading and retrying...');
                frm.reload_doc();
                setTimeout(function() {
                    frm.save().then(function() {
                        console.log('✓ Document saved after reload');
                        frappe.show_alert({ message: __('PCB data updated successfully'), indicator: 'green' }, 5);
                        frm.clear_table('pcb_iqc_data_enter');
                        frm.refresh_field('pcb_iqc_data_enter');
                    }).catch(function(retry_err) {
                        console.error('ERROR on retry save:', retry_err);
                        frappe.msgprint(__('Error saving document: {0}', [retry_err.message || 'Unknown error']));
                    });
                }, 500);
            } else {
                frappe.msgprint(__('Error saving document: {0}', [err_msg]));
            }
        });
    } catch(e) {
        console.error('ERROR in submit_pcb_data:', e);
        console.error('Error stack:', e.stack);
        frappe.msgprint(__('Error: {0}', [e.message || 'Unknown error']));
    }
}

