// This ensures no handler overrides occur.

// Helper function to calculate overall status from PTS1, PTS2, PTS3
function calculate_overall_status_from_pts(pts1, pts2, pts3) {
    // Normalize inputs - handle null, undefined, empty strings, whitespace
    pts1 = String(pts1 || 'Pending').trim();
    pts2 = String(pts2 || 'Pending').trim();
    pts3 = String(pts3 || 'Pending').trim();

    // Rule 1: If any one = Fail → Overall = Fail
    if (pts1 === 'Fail' || pts2 === 'Fail' || pts3 === 'Fail') {
        return 'Fail';
    }

    // Rule 2: Else if all three = Pass → Overall = Pass
    if (pts1 === 'Pass' && pts2 === 'Pass' && pts3 === 'Pass') {
        return 'Pass';
    }

    // Rule 3: Else → Overall = Pending
    return 'Pending';
}

function update_pts_status(frm, cdt, cdn, pts_type) {
    let row = locals[cdt][cdn];

    // If status is set back to Pending, clear the corresponding date.
    if (row[pts_type + '_status'] === 'Pending') {
        if (row[pts_type + '_date']) {
            frappe.model.set_value(cdt, cdn, pts_type + '_date', null);
        }
    } else if (row[pts_type + '_status']) {
        // If status is not Pending and date missing, set date.
        if (!row[pts_type + '_date']) {
            frappe.model.set_value(cdt, cdn, pts_type + '_date', frappe.datetime.now_datetime());
        }
    }

    let pts1 = row.pts1_status || 'Pending';
    let pts2 = row.pts2_status || 'Pending';
    let pts3 = row.pts3_status || 'Pending';

    // Use the helper function to calculate overall status
    let overall = calculate_overall_status_from_pts(pts1, pts2, pts3);

    frappe.model.set_value(cdt, cdn, 'overall_status', overall);
    setTimeout(() => apply_status_colors(frm), 100);
}
